import '../contact/Contact.css';
import React from 'react';
import { Form, Col, Row, Button } from 'react-bootstrap';
import { useState } from 'react';
//import { Alert } from 'react-bootstrap';
import AlertMsg from '../../components/modals/AlertMsg';



const Contact = () => {
    const [modalShow, setModalShow] = useState(null);
    const [firstName,setFirstName] = useState("");
    const [lastName,setLastName] = useState("");
    const [email,setEmail] = useState("");
    const [message,setMessage] = useState("");
    const [data,setData] = useState([]);
    //const [alert, setAlert] = useState(null);

    /*function AlertMsg(props) {
      //  return (
        //    props.alert && <Alert className='text-center mt-1 mx-3' variant={`${props.alert.type}`}>
          //    <p>
            //    {props.alert.type}: {props.alert.msg}
              </p>
            </Alert>
        );
    }*/

    const showAlert = (message, type) => {
        setModalShow({
            msg: message,
            type: type
        })
        setTimeout(() => {
            setModalShow(null);
        }, 2500);
    }

    const submitHandler = (e) => {
        e.preventDefault();

        const newUser = {
            firstName: firstName,
            lastName: lastName,
            email: email,
            message: message
        }
        setData([...data, newUser]);
        setFirstName("");
        setLastName("");
        setEmail("");
        setMessage("");  


        if (firstName === '' || lastName === '' || email === '' || message === ''){
            showAlert("All fields are requied", "warning");
        }

        else
            showAlert("Thank You. Your message has been sent!", "success");
    };

    return (
        <>
            {/*<AlertMsg alert={alert}/>*/}
            <Msgmodal show={modalShow}/>
            <Form className="container border border-primary border-2 rounded-3 col-lg-7 col-11 mt-auto p-2 text-white bg-info bg-opacity-10" onSubmit={submitHandler}>

                <Row className="mb-3">
                    <Form.Group as={Col} controlId="firstName">
                        <Form.Label>First Name</Form.Label>
                        <Form.Control type="text" placeholder="First Name" value={firstName} onChange = {(e) => {setFirstName(e.target.value)}} required />
                    </Form.Group>

                    <Form.Group as={Col} controlId="lastName">
                        <Form.Label>Last Name</Form.Label>
                        <Form.Control type="text" placeholder="Last Name" value={lastName} onChange = {(e)=> {setLastName(e.target.value)}} required />
                    </Form.Group>
                </Row>

                <Form.Group className="mb-3" controlId="email">
                    <Form.Label>Email</Form.Label>
                    <Form.Control type="email" placeholder="Email" value={email} onChange = {(e)=> {setEmail(e.target.value)}} required />
                </Form.Group>

                <Form.Group className="mb-3" controlId="message">
                    <Form.Label>Your Message</Form.Label>
                    <Form.Control as="textarea" aria-label="With textarea" value={message} onChange = {(e) => {setMessage(e.target.value)}} required/>
                </Form.Group>

                <div className="text-center">

                    <Button variant="danger" type='submit' onClick={submitHandler}>
                        Send
                    </Button>

                    {/*alert && <AlertMsg showAlert = {alert} onHide={()=> setAlert(false)}/>*/}

                </div>

               {modalShow && <Msgmodal
                    show={modalShow}
                    onHide={() => setModalShow(false)}
                />}

            </Form>

        </>
    );
}

export default Contact;
